import { useEffect, useState } from 'react';
import { fetchThreadPage, pageCount, type ThreadPage } from '../../lib/threads';
import type { MemberProfile } from '../../lib/session';
import { ThreadList } from './ThreadList';
import styles from './Messages.module.css';

interface MessagesProps {
  profile: MemberProfile;
  /** Inyectable para que los tests no dependan del reloj. */
  now?: Date;
  /** La pasa el shell desde App.tsx (congelación F-118 del corpus). MSG-02 no
      existe en este alcance: la recibimos y la ignoramos — abrir no lleva a
      ninguna parte. */
  onOpenThread?: (threadId: string) => void;
}

/**
 * Convierte el error capturado en texto que el usuario pueda leer.
 *
 * F-128: PostgREST no lanza un `Error` sino un objeto plano `{ code, message }`.
 * `String(e)` daría `[object Object]` y `e.message` daría `undefined`, así que
 * hay que sacar `code` y/o `message` cuando existan y pintarlos junto a la
 * frase para humanos.
 */
function describeError(e: unknown): string {
  if (e instanceof Error) return e.message;
  if (typeof e === 'object' && e !== null) {
    const rec = e as Record<string, unknown>;
    const parts: string[] = [];
    if (typeof rec.code === 'string' && rec.code.trim() !== '') parts.push(rec.code);
    if (typeof rec.message === 'string' && rec.message.trim() !== '') parts.push(rec.message);
    if (parts.length > 0) return parts.join(' · ');
  }
  return String(e);
}

/**
 * MSG-01 · Lista de Hilos. La pantalla, no un componente de presentación:
 * posee el estado de búsqueda y de página y llama a `fetchThreadPage`.
 */
export function Messages({ profile, now = new Date() }: MessagesProps) {
  const [term, setTerm] = useState('');
  const [search, setSearch] = useState('');
  const [page, setPage] = useState(1);
  const [data, setData] = useState<ThreadPage | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<unknown>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    fetchThreadPage({ orgId: profile.orgId, search, page })
      .then((res) => {
        if (cancelled) return;
        setData(res);
        setLoading(false);
      })
      .catch((e: unknown) => {
        if (cancelled) return;
        setError(e);
        setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [profile.orgId, search, page]);

  const total = data?.total ?? 0;
  const threads = data?.threads ?? [];
  const pages = pageCount(total);

  return (
    <div className={styles.screen}>
      <p className={styles.eyebrow}>Módulo 04 · Mensajería E2EE</p>
      <h1 className={styles.title}>Hilos</h1>
      <p className={styles.sub}>
        Tus conversaciones con otros distribuidores. Todo el contenido está cifrado de extremo a extremo.
      </p>

      <div className={styles.actionsBar}>
        <form
          className={styles.searchForm}
          onSubmit={(e) => {
            e.preventDefault();
            setSearch(term);
            setPage(1);
          }}
        >
          <i className="ti ti-search" aria-hidden="true" />
          <input
            type="text"
            className={styles.searchInput}
            placeholder="Buscar por nombre de organización..."
            value={term}
            onChange={(e) => setTerm(e.target.value)}
          />
        </form>
        {/* DIR-01 no está entre las 8 pantallas del MVP: el control existe pero
            deshabilitado, con el motivo como tooltip — misma forma que el botón
            de subida de INV-01 (F-023 e). */}
        <button
          type="button"
          className={styles.primaryBtn}
          disabled
          title="El Directorio queda fuera del MVP"
        >
          <i className="ti ti-address-book" aria-hidden="true" />
          Nuevo contacto
        </button>
        <span className={styles.threadCount}>
          {total} {total === 1 ? 'hilo' : 'hilos'} · Página {page} de {pages}
        </span>
      </div>

      {error ? (
        <div role="alert" className={styles.error}>
          No se pudieron cargar los hilos. {describeError(error)}
        </div>
      ) : loading && !data ? (
        <div className={styles.loading}>Cargando hilos…</div>
      ) : (
        <>
          <ThreadList threads={threads} now={now} onOpen={() => {}} />
          {threads.length > 0 && (
            <div className={styles.pagination}>
              <button
                type="button"
                className={styles.pageBtn}
                disabled={page <= 1}
                onClick={() => setPage((p) => Math.max(1, p - 1))}
                aria-label="Página anterior"
              >
                ‹
              </button>
              {Array.from({ length: pages }, (_, i) => i + 1).map((n) => (
                <button
                  key={n}
                  type="button"
                  className={`${styles.pageBtn} ${n === page ? styles.pageActive : ''}`}
                  aria-current={n === page ? 'page' : undefined}
                  onClick={() => setPage(n)}
                >
                  {n}
                </button>
              ))}
              <button
                type="button"
                className={styles.pageBtn}
                disabled={page >= pages}
                onClick={() => setPage((p) => Math.min(pages, p + 1))}
                aria-label="Página siguiente"
              >
                ›
              </button>
            </div>
          )}
        </>
      )}
    </div>
  );
}

